<?php
namespace App\Services;
use App\Models\{Notification,User};
class RequestNotifier {public function __construct(private WebPushService $push){}public function created(object $request,string $label):void{$employee=$request->user;$recipients=User::where(fn($q)=>$q->whereKey($employee->manager_id)->orWhereIn('role',['admin','manage_admin','super_admin']))->get();$employee->departmentRelation?->hods()->get()->each(fn($u)=>$recipients->push($u));foreach($recipients->unique('id') as $u){$title="New $label request";$message="{$employee->name} submitted a $label request.";$url=$label==='leave'?'/leaves':'/edit-requests';Notification::create(['user_id'=>$u->id,'type'=>'request_created','title'=>$title,'message'=>$message,'scope_type'=>'employee','scope_id'=>$employee->id,'department_name'=>$employee->department,'url'=>$url]);$this->push->send($u,$title,$message,$url);}}public function decided(object $request,string $label,string $status):void{$title=ucfirst($label).' request updated';$message="Your $label request is now ".str_replace('_',' ',$status).'.';$url=$label==='leave'?'/my-leaves':'/my-edit-requests';Notification::create(['user_id'=>$request->user_id,'type'=>'request_decided','title'=>$title,'message'=>$message,'scope_type'=>'employee','scope_id'=>$request->user_id,'department_name'=>$request->user->department,'url'=>$url]);$this->push->send($request->user,$title,$message,$url);}}
